// Desktop 2.0 snapshot: src/main/streamProxy.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Локальный HTTP-прокси для звука (только 127.0.0.1, наружу не виден).
// Зачем: <audio> не умеет повторять запрос, если сервер ответил 403,
// а ссылки YouTube иногда так отвечают (см. этап 0 и тест окна).
// Прокси пересылает запросы с Range (нужно для перемотки), при ошибке повторяет,
// а если не помогает, просит у yt-dlp свежую ссылку.
import { createReadStream, statSync } from 'node:fs';
import http from 'node:http';
import { randomBytes } from 'node:crypto';
import { Readable } from 'node:stream';
import type { AddressInfo } from 'node:net';
import type { FetchFn, StreamInfo } from './resolver/types.js';

interface Entry {
  stream: StreamInfo;
  /** Получить новую ссылку на тот же трек (старая протухла или не пускает). */
  refresh: () => Promise<StreamInfo | null>;
  /** Чтобы два параллельных запроса не обновляли ссылку одновременно. */
  refreshing?: Promise<StreamInfo | null>;
}

const MAX_TRIES = 4;
/** Сколько последних треков помнить. Старые токены удаляются. */
const MAX_ENTRIES = 30;
/** Заголовки ответа, которые передаём в <audio>. */
const PASS_HEADERS = ['content-type', 'content-length', 'content-range', 'accept-ranges', 'last-modified', 'etag'];

/** Сколько первых байт песни загружать заранее (версия 1.4): звук начинается сразу из памяти. */
const HEAD_BYTES = 384 * 1024;
/** Сколько таких начал держать в памяти (около 8 МБ). */
const MAX_HEADS = 20;

/**
 * Звук идёт в Web Audio (версия 1.7, renderer/audioChain.ts), а <audio> открывает его с crossOrigin.
 * Без этого заголовка Chromium отдаёт в цепочку тишину. Сервер слушает только 127.0.0.1.
 */
const CORS = { 'access-control-allow-origin': '*' };

/** Типы картинок по расширению (обложки плейлистов и скачанных песен). */
const IMAGE_TYPES: Record<string, string> = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };

export class StreamProxy {
  private server: http.Server | null = null;
  private port = 0;
  private entries = new Map<string, Entry>();
  /** Скачанные файлы для <audio>: токен -> файл и его тип. */
  private files = new Map<string, { path: string; mime: string }>();
  /** Начала песен, загруженные заранее: адрес потока -> первые байты, полный размер и тип. */
  private heads = new Map<string, Promise<{ buf: Buffer; total: number; type: string } | null>>();
  /** Папки с картинками: /img/<папка>/<имя>. */
  private imageDirs = new Map<string, (name: string) => string | null>();

  constructor(private fetchFn: FetchFn) {}

  /** Запускает сервер на свободном порту. */
  async start(): Promise<void> {
    if (this.server) return;
    this.server = http.createServer((req, res) => void this.handle(req, res));
    await new Promise<void>((resolve) => this.server!.listen(0, '127.0.0.1', resolve));
    this.port = (this.server.address() as AddressInfo).port;
    console.log(`[proxy] слушаю http://127.0.0.1:${this.port}`);
  }

  /** Регистрирует поток и возвращает локальную ссылку для <audio>. */
  register(stream: StreamInfo, refresh: Entry['refresh']): string {
    const token = randomBytes(12).toString('hex');
    this.entries.set(token, { stream, refresh });
    while (this.entries.size > MAX_ENTRIES) {
      this.entries.delete(this.entries.keys().next().value!);
    }
    return `http://127.0.0.1:${this.port}/s/${token}`;
  }

  /**
   * Загрузить начало песни заранее (ссылка уже готова, песню вот-вот включат).
   * Тогда <audio> получает первые сотни килобайт из памяти и начинает играть без ожидания сети,
   * а остальное просит обычным запросом с Range (так браузер делает всегда, когда ответ короче файла).
   */
  preload(stream: StreamInfo): void {
    if (stream.protocol !== 'http' || this.heads.has(stream.url)) return;
    const ua: Record<string, string> = stream.headers['User-Agent'] ? { 'User-Agent': stream.headers['User-Agent'] } : {};
    const p = (async () => {
      try {
        const res = await this.fetchFn(stream.url, { headers: { ...ua, Range: `bytes=0-${HEAD_BYTES - 1}` } });
        const m = /\/(\d+)$/.exec(res.headers.get('content-range') ?? '');
        if (res.status !== 206 || !m) {
          await res.body?.cancel();
          return null;
        }
        return { buf: Buffer.from(await res.arrayBuffer()), total: Number(m[1]), type: res.headers.get('content-type') ?? 'application/octet-stream' };
      } catch {
        return null;
      }
    })();
    this.heads.set(stream.url, p);
    while (this.heads.size > MAX_HEADS) this.heads.delete(this.heads.keys().next().value!);
  }

  /** Запрос <audio> с начала файла, а начало уже в памяти: отдаём его сразу. */
  private async sendHead(req: http.IncomingMessage, res: http.ServerResponse, url: string): Promise<boolean> {
    const m = /^bytes=0-(\d*)$/.exec(req.headers.range ?? 'bytes=0-');
    const pending = this.heads.get(url);
    if (!m || !pending) return false;
    const head = await pending;
    if (!head || !head.buf.length) return false;
    const want = m[1] ? Math.min(Number(m[1]) + 1, head.total) : head.total;
    const len = Math.min(want, head.buf.length);
    res.writeHead(206, {
      ...CORS,
      'content-type': head.type,
      'accept-ranges': 'bytes',
      'content-length': String(len),
      'content-range': `bytes 0-${len - 1}/${head.total}`,
    });
    res.end(req.method === 'HEAD' ? undefined : head.buf.subarray(0, len));
    return true;
  }

  /** Скачанный файл: локальная ссылка для <audio> (с перемоткой). */
  registerFile(file: string, mime: string): string {
    const token = randomBytes(12).toString('hex');
    this.files.set(token, { path: file, mime });
    while (this.files.size > MAX_ENTRIES) this.files.delete(this.files.keys().next().value!);
    return `http://127.0.0.1:${this.port}/f/${token}`;
  }

  /** Отдавать картинки из папки: resolve(имя) даёт полный путь или null. */
  serveImages(prefix: string, resolve: (name: string) => string | null): void {
    this.imageDirs.set(prefix, resolve);
  }

  /** Адрес картинки для окна. */
  imageUrl(prefix: string, name: string): string {
    return `http://127.0.0.1:${this.port}/img/${prefix}/${encodeURIComponent(name)}`;
  }

  /** Файл с диска с поддержкой Range (перемотка). */
  private sendFile(req: http.IncomingMessage, res: http.ServerResponse, file: string, mime: string): void {
    let size: number;
    try {
      size = statSync(file).size;
    } catch {
      res.writeHead(404).end();
      return;
    }
    const m = /^bytes=(\d*)-(\d*)$/.exec(req.headers.range ?? '');
    let start = 0;
    let end = size - 1;
    if (m) {
      if (m[1]) start = Number(m[1]);
      if (m[2]) end = Math.min(size - 1, Number(m[2]));
      if (!m[1] && m[2]) start = Math.max(0, size - Number(m[2]));
      if (start > end || start >= size) {
        res.writeHead(416, { 'content-range': `bytes */${size}` }).end();
        return;
      }
    }
    const headers = {
      ...CORS,
      'content-type': mime,
      'accept-ranges': 'bytes',
      'content-length': String(end - start + 1),
      ...(m ? { 'content-range': `bytes ${start}-${end}/${size}` } : {}),
      'cache-control': 'no-store',
    };
    res.writeHead(m ? 206 : 200, headers);
    if (req.method === 'HEAD') {
      res.end();
      return;
    }
    createReadStream(file, { start, end }).on('error', () => res.destroy()).pipe(res);
  }

  private async freshStream(entry: Entry, failedUrl: string): Promise<void> {
    if (entry.stream.url !== failedUrl) return; // уже обновили в другом запросе
    entry.refreshing ??= entry.refresh().finally(() => (entry.refreshing = undefined));
    const s = await entry.refreshing;
    if (s) entry.stream = s;
  }

  private async handle(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
    const f = /^\/f\/([0-9a-f]+)$/.exec(req.url ?? '');
    if (f && (req.method === 'GET' || req.method === 'HEAD')) {
      const file = this.files.get(f[1]);
      if (!file) res.writeHead(404).end();
      else this.sendFile(req, res, file.path, file.mime);
      return;
    }
    const img = /^\/img\/(\w+)\/([^/?]+)$/.exec(req.url ?? '');
    if (img && req.method === 'GET') {
      const name = decodeURIComponent(img[2]);
      const full = this.imageDirs.get(img[1])?.(name);
      const type = IMAGE_TYPES[name.split('.').pop()?.toLowerCase() ?? ''];
      if (!full || !type) res.writeHead(404).end();
      else this.sendFile(req, res, full, type);
      return;
    }
    const m = /^\/s\/([0-9a-f]+)$/.exec(req.url ?? '');
    const entry = m ? this.entries.get(m[1]) : undefined;
    if (!entry || (req.method !== 'GET' && req.method !== 'HEAD')) {
      res.writeHead(404).end();
      return;
    }
    if (await this.sendHead(req, res, entry.stream.url)) return;

    // Если <audio> перестал ждать (перемотка, смена трека), обрываем загрузку
    const abort = new AbortController();
    res.on('close', () => abort.abort());

    const range = req.headers.range;
    let lastStatus = 0;
    for (let attempt = 1; attempt <= MAX_TRIES && !abort.signal.aborted; attempt++) {
      const url = entry.stream.url;
      try {
        const up = await this.fetchFn(url, {
          method: req.method,
          headers: {
            ...(range ? { Range: range } : {}),
            ...(entry.stream.headers['User-Agent'] ? { 'User-Agent': entry.stream.headers['User-Agent'] } : {}),
          },
          signal: abort.signal,
        });
        lastStatus = up.status;
        if (up.ok) {
          const headers: Record<string, string> = { ...CORS };
          for (const h of PASS_HEADERS) {
            const v = up.headers.get(h);
            if (v) headers[h] = v;
          }
          res.writeHead(up.status, headers);
          if (req.method === 'HEAD' || !up.body) {
            res.end();
            return;
          }
          Readable.fromWeb(up.body as import('node:stream/web').ReadableStream)
            .on('error', () => res.destroy())
            .pipe(res);
          if (attempt > 1) console.log(`[proxy] получилось с попытки ${attempt}`);
          return;
        }
        // Неверный диапазон: повторять бессмысленно
        if (up.status === 416) break;
        await up.body?.cancel();
        console.warn(`[proxy] сервер ответил ${up.status}, попытка ${attempt}/${MAX_TRIES}`);
      } catch (e) {
        if (abort.signal.aborted) return;
        console.warn(`[proxy] сетевая ошибка: ${(e as Error).message}, попытка ${attempt}/${MAX_TRIES}`);
      }
      // После второй неудачи берём свежую ссылку, иначе просто ждём чуть-чуть
      if (attempt >= 2) await this.freshStream(entry, url);
      else await new Promise((r) => setTimeout(r, 300));
    }
    if (!res.headersSent) res.writeHead(lastStatus || 502).end();
  }
}
